//! `Wallpaper/WallpaperPicker/builtinPosters.ts`: the bundled 320x200 PNG stills of the built-in
//! live modules (generated by the React engine; the order is the generated file's). The WebGL
//! engine is P6, so these stand in for a module drawn with its default params.
use std::collections::HashMap;
use std::sync::{Arc, Mutex, OnceLock, PoisonError};

use gpui::{Image, ImageFormat};

use super::WallpaperTone;

/// Drawing-buffer size of a poster. // DS: WallpaperPicker/pickerTiles.ts:21
pub const POSTER_SIZE: (u32, u32) = (320, 200);

macro_rules! poster {
    ($module:literal, $tone:literal) => {
        (
            $module,
            $tone,
            include_bytes!(concat!("../../../../assets/wallpaper/butler.", $module, ".", $tone, ".png"))
                .as_slice(),
        )
    };
}

const POSTERS: &[(&str, &str, &[u8])] = &[
    poster!("riso-print", "light"),
    poster!("bloom", "light"),
    poster!("silk", "light"),
    poster!("riso-flow", "light"),
    poster!("lamina", "light"),
    poster!("diatom", "light"),
    poster!("dusk", "light"),
    poster!("shoreline", "light"),
    poster!("photo-clouds", "light"),
    poster!("photo-daisies", "light"),
    poster!("stipple", "light"),
    poster!("riso-print", "dark"),
    poster!("bloom", "dark"),
    poster!("silk", "dark"),
    poster!("riso-flow", "dark"),
    poster!("lamina", "dark"),
    poster!("diatom", "dark"),
    poster!("dusk", "dark"),
    poster!("shoreline", "dark"),
    poster!("photo-clouds", "dark"),
    poster!("photo-daisies", "dark"),
    poster!("stipple", "dark"),
];

static DECODED: OnceLock<Mutex<HashMap<(&'static str, &'static str), Arc<Image>>>> = OnceLock::new();

fn tone_name(tone: WallpaperTone) -> &'static str {
    match tone {
        WallpaperTone::Light => "light",
        WallpaperTone::Dark => "dark",
    }
}

/// The ids of the modules that have a poster, in the generated order (light, then dark).
pub fn poster_modules() -> impl Iterator<Item = &'static str> {
    POSTERS
        .iter()
        .filter(|(_, tone, _)| *tone == "light")
        .map(|(module, _, _)| module)
        .copied()
}

/// The poster of a `butler.<name>` module id (the id without its `butler.` prefix is also
/// accepted) for a tone, shared between callers; `None` for a module without one.
pub fn builtin_poster(module: &str, tone: WallpaperTone) -> Option<Arc<Image>> {
    let name = module.strip_prefix("butler.").unwrap_or(module);
    let tone = tone_name(tone);
    let (module, tone, bytes) = POSTERS
        .iter()
        .find(|(candidate, candidate_tone, _)| *candidate == name && *candidate_tone == tone)?;
    let mut decoded = DECODED
        .get_or_init(Default::default)
        .lock()
        .unwrap_or_else(PoisonError::into_inner);
    let image = decoded
        .entry((*module, *tone))
        .or_insert_with(|| Arc::new(Image::from_bytes(ImageFormat::Png, bytes.to_vec())));
    Some(Arc::clone(image))
}
